module top_module(
  input [15:0] tx_data,
  input tx_enable,
  input tx_clk,
  output tx_out,
  output tx_busy,
  input [15:0] rx_data,
  input rx_enable,
  input rx_clk,
  output rx_out,
  output rx_busy
);// Transmitter
  reg [23:0] tx_encoded_data;
  reg tx_busy_reg;
  always @(posedge tx_clk) begin
    if (tx_enable) begin
      tx_busy_reg <= 1;
      tx_encoded_data <= {4'b1010, tx_data, 4'b1100, 16'hFFFF}; // Preamble, data, start delimiter, CRC
    end else begin
      tx_busy_reg <= 0;
    end
  end

  assign tx_busy = tx_busy_reg;

  // FSK Modulation
  reg [1:0] tx_modulated_data;
  always @(posedge tx_clk) begin
    if (tx_enable) begin
      case (tx_encoded_data[1:0])
        2'b00: tx_modulated_data <= 2'b01;
        2'b01: tx_modulated_data <= 2'b00;
        2'b10: tx_modulated_data <= 2'b11;
        2'b11: tx_modulated_data <= 2'b10;
      endcase
    end
  end

  assign tx_out = tx_modulated_data[0];

  // Receiver
  reg [23:0] rx_demodulated_data;
  reg rx_busy_reg;
  always @(posedge rx_clk) begin
    if (rx_enable) begin
      rx_busy_reg <= 1;
      case (rx_data[1:0])
        2'b00: rx_demodulated_data[1:0] <= 2'b01;
        2'b01: rx_demodulated_data[1:0] <= 2'b00;
        2'b10: rx_demodulated_data[1:0] <= 2'b11;
        2'b11: rx_demodulated_data[1:0] <= 2'b10;
      endcase
    end else begin
      rx_busy_reg <= 0;
    end
  end

  assign rx_busy = rx_busy_reg;

  // Decoding
  reg [15:0] rx_decoded_data;
  always @(posedge rx_clk) begin
    if (rx_enable) begin
      if (rx_demodulated_data[23:20] == 4'b1010 && rx_demodulated_data[3:0] == 4'b1100) begin
        rx_decoded_data <= rx_demodulated_data[19:4];
      end
    end
  end

  assign rx_out = rx_decoded_data[0];

endmodule

