	if (reset) begin
		o_x <= {BIT_WIDTH{1'b0}};
		o_y <= {BIT_WIDTH{1'b0}};
		o_z <= {BIT_WIDTH{1'b0}};
	end else if (enable) begin
		o_x <= i_x;
		o_y <= i_y;
