module fsm (
	input clk,
	input reset_n,
	input r,
	input s,
	output reg t);

	parameter Z=0, W=1, S1=2, S2=3, S3=4, S4=5;
	reg [2:0] state, next;

	always @(posedge clk) begin
		if (!reset_n) state <= Z;
		else state <= next;
	end

	always_comb begin
		case (state)
			Z: next = r ? W : Z;
			W: next = s ? S1 : S2;
			S1: next = s ? S2 : S3;
			S2: next = s ? S3 : S4;
			S3: next = s ? S4 : Z;
			S4: next = r ? W : Z;
			default: next = 'x;
		endcase
	end

	assign t = (state == S1);

endmodule

