module gray_counter_5bit(
    input clk, 
    input reset, 
    output reg [4:0] gray);

    reg [4:0] binary_count;

    always @(posedge clk) begin
        if (reset)
            binary_count <= 5'b00000;
        else
            binary_count <= binary_count + 1;
    end

    always @(posedge clk) begin
        if (reset)
            gray <= 5'b00000;
        else
            gray <= (binary_count >> 1) ^ binary_count;
    end
endmodule

