        input clk,
        input rst,
        input go,
        input done,
        output reg out);

    parameter READY = 0, RUNNING = 1, FINISHED = 2;
    reg [1:0] state, next_state;

    always @(posedge clk) begin
        if (rst) state <= READY;
        else state <= next_state;
    end

    always_comb begin
        case (state)
            READY: next_state = go ? RUNNING : READY;
            RUNNING: next_state = done ? FINISHED : RUNNING;
            FINISHED: next_state = rst ? READY : FINISHED;
            default: next_state = 'x;
        endcase
    end

    assign out = (state == RUNNING) || (state == FINISHED);

endmodule

