module top_module(
	clk, 
	rst_n, 
	in_enable, 
	in_data, 
	ref_enable, 
	ref_data, 
	out_ready, 
	out_data);parameter[0 : 0] work_mode = 0;

	parameter[3 : 0] in_window_width = 1;

	parameter[3 : 0] color_width = 8;

	parameter max_delay = 8;

	parameter max_delay_bits = 4;


	input clk;

	input rst_n;

	input in_enable;

	input [color_width * in_window_width * in_window_width - 1 : 0] in_data;

	input ref_enable;

	input[color_width - 1 : 0] ref_data;

	output out_ready;

	output out_data;

	reg reg_out_ready;
	reg reg_out_data;
	reg[max_delay_bits - 1 : 0] con_out;

	genvar i, j;
	generate

		if(work_mode == 0) begin
			reg[color_width - 1 : 0] buffer[0 : max_delay - 1];
			wire[max_delay - 1 : 0] res;
			always @(posedge clk or negedge rst_n or negedge in_enable) begin
				if(~rst_n || ~in_enable)
					con_out <= 0;
				else if(con_out == max_delay)
					con_out <= con_out;
				else if(~ref_enable)
					con_out <= con_out + 1;
				else
					con_out <= con_out;
			end
			always @(posedge clk or negedge rst_n or negedge ref_enable) begin
				if(~rst_n || ~ref_enable) begin
					reg_out_ready <= 0;
					reg_out_data <= 0;
				end else begin
					reg_out_ready <= 1;
					reg_out_data <= res[con_out - 1];
				end
			end
			for (i = 0; i < max_delay; i = i + 1) begin
				if(i == 0) begin 
					always @(posedge clk)
						buffer[i] <= in_data[((in_window_width * in_window_width >> 1) + 1) * color_width - 1 : (in_window_width * in_window_width >> 1) * color_width];
				end else begin 
					always @(posedge clk)
						buffer[i] <= buffer[i - 1];
				end
				assign res[i] = buffer[i] < ref_data ? 0 : 1;
			end
		end else begin 
			always @(posedge clk or negedge rst_n or negedge ref_enable) begin
				if(~rst_n || ~ref_enable) begin
					reg_out_ready <= 0;
					reg_out_data <= 0;
				end else begin
					reg_out_ready <= 1;
					reg_out_data <= in_data < ref_data ? 0 : 1;
				end
			end
		end

		assign out_ready = reg_out_ready;
		assign out_data = reg_out_data;
	endgenerate

endmodule

module top_module(
  input clk,
  input [6:0] addr,
  input [15:0] di,
  input we,
  input eoc,
  output reg busy,
  output reg [4:0] channel,
  output reg [15:0] dout,
  output reg drdy,
  output reg eoc_out,
  output reg [2:0] jtag_busy,  // Changed to reg
  output reg jtag_locked,      // Changed to reg
  output reg jtag_modified     // Changed to reg
);localparam IDLE = 3'b000, READ = 3'b001, PROCESS = 3'b010, WRITE = 3'b011;
  reg [2:0] state;
  reg [15:0] data;

  always @(posedge clk) begin
    case (state)
      IDLE: begin
        busy <= 0;
        channel <= 0;
        dout <= 0;
        drdy <= 0;
        eoc_out <= 0;
        jtag_busy <= 0;         // Can now assign because jtag_busy is reg
        jtag_locked <= 0;       // Can now assign because jtag_locked is reg
        jtag_modified <= 0;     // Can now assign because jtag_modified is reg
        if (eoc) begin
          state <= READ;
        end
      end
      READ: begin
        busy <= 1;
        channel <= addr[4:0];
        dout <= 16'h0000;
        drdy <= 0;
        eoc_out <= 0;
        jtag_busy <= 0;         // Can now assign because jtag_busy is reg
        jtag_locked <= 0;       // Can now assign because jtag_locked is reg
        jtag_modified <= 0;     // Can now assign because jtag_modified is reg
        state <= PROCESS;
      end
      PROCESS: begin
        busy <= 1;
        channel <= addr[4:0];
        dout <= 16'h0000;
        drdy <= 0;
        eoc_out <= 0;
        jtag_busy <= 0;         // Can now assign because jtag_busy is reg
        jtag_locked <= 0;       // Can now assign because jtag_locked is reg
        jtag_modified <= 0;     // Can now assign because jtag_modified is reg
        if (!eoc) begin
          state <= PROCESS;
        end else begin
          state <= WRITE;
        end
      end
      WRITE: begin
        busy <= 1;
        channel <= addr[4:0];
        dout <= data;
        drdy <= 1;
        eoc_out <= 1;
        jtag_busy <= 0;         // Can now assign because jtag_busy is reg
        jtag_locked <= 0;       // Can now assign because jtag_locked is reg
        jtag_modified <= 0;     // Can now assign because jtag_modified is reg
        if (!we) begin
          state <= IDLE;
        end
      end
    endcase
  end

  always @(posedge clk) begin
    case (state)
      IDLE: begin
        data <= 16'h0000;
      end
      READ: begin
        data <= 16'h0000;
      end
      PROCESS: begin
        data <= di;
      end
      WRITE: begin
        data <= 16'h0000;
      end
    endcase
  end

endmodule

