module fsm_module (
        input clk,
        input reset,
        input signal,
        output reg out);parameter T0=0, T1=1, T2=2, T3=3;
	reg[1:0] state, next;

	always @(posedge clk)
		if (reset) state <= T0;
		else state <= next;

	always_comb begin
		case (state)
			T0: next = signal ? T1 : T0;
			T1: next = signal ? T2 : T1;
			T2: next = signal ? T3 : T2;
			T3: next = signal ? T0 : T3;
			default: next = 'x;
		endcase
	end

	assign out = (state == T1) || (state == T3);

endmodule

