module top_module (
	input clk,
	input areset,
	input x,
	input y,
	output z,
	output carry_out);parameter S0=0,S1=1;
	reg state, carry;
	always @(posedge clk, posedge areset) begin
		if (areset) begin
			state <= S0;
			carry <= 0;
		end
		else begin
			carry <= (x & y) | (carry & (x | y));
			state <= x ^ y ^ carry;
		end
	end

	assign z = state;
	assign carry_out = carry;

endmodule

