module fsm (
	input clk,
	input reset,
	input p,
	input q,
	output reg n);

	parameter S=0, T=1, U1=2, U2=3, U3=4, U4=5;
	reg [2:0] state, next;

	always @(posedge clk) begin
		if (reset) state <= S;
		else state <= next;
	end

	always_comb begin
		case (state)
			S: next = p ? T : S;
			T: next = q ? U1 : U2;
			U1: next = q ? U2 : U3;
			U2: next = q ? U3 : U4;
			U3: next = p ? T : S;
			U4: next = p ? T : S;
			default: next = 'x;
		endcase
	end

	assign n = (state == U3 && q);

endmodule

