module fsm_module (
        input clk,
        input reset,
        input enable,
        output reg out);parameter Y0=0, Y1=1, Y2=2, Y3=3;
	reg[1:0] state, next;

	always @(posedge clk)
		if (reset) state <= Y0;
		else state <= next;


	always_comb begin
		case (state)
			Y0: next = enable ? Y1 : Y0;
			Y1: next = enable ? Y2 : Y1;
			Y2: next = enable ? Y3 : Y2;
			Y3: next = enable ? Y0 : Y3;
			default: next = 'x;
		endcase
	end

	assign out = (state == Y1) || (state == Y3);

endmodule

