module fsm (
        input clk,
        input reset,
        input d,
        output reg y);parameter K0=0, K1=1, K2=2, K3=3, K4=4;
	reg [2:0] state, next;

	always @(posedge clk)
		if (reset)
			state <= K0;
		else 
			state <= next;


	always_comb begin
		case(state)
			K0: next = d ? K1 : K2;
			K1: next = d ? K4 : K3;
			K2: next = d ? K3 : K0;
			K3: next = d ? K4 : K1;
			K4: next = d ? K0 : K2;
			default: next = 'x;
		endcase
	end

	assign y = (state == K1 || state == K3 || state == K4);

endmodule

