module top_module(
  input wire A1,
  input wire A2,
  input wire A3,
  input wire B1,
  input wire B2,
  input wire VPWR,
  input wire VGND,
  input wire VPB,
  input wire VNB,
  output wire X
);reg A1_reg;
  reg A2_reg;
  reg A3_reg;
  reg B1_reg;
  reg B2_reg;

  assign X = A1_reg & A2_reg & A3_reg & B1_reg & B2_reg;

  always @(posedge VPWR, negedge VGND) begin
    A1_reg <= A1;
    A2_reg <= A2;
    A3_reg <= A3;
    B1_reg <= B1;
    B2_reg <= B2;
  end

endmodule

module top_module(oh1,control,literal);input [13:0] oh1;
output reg [15:0] literal;
output reg [25:0] control;
always @(*) begin
    case (oh1[13:9])
        5'b110xx, 5'b111xx: begin 
            control = {8'b01100000,oh1[10:8],14'b000101};
            literal = {oh1[7],oh1[7],oh1[7],oh1[7],oh1[7],oh1[7],oh1[7],oh1[7],oh1[7:0]}; 
        end //brz
        5'b100xx, 5'b101xx: begin 
            control = {8'b01100000,oh1[10:8],14'b00010110100000};
            literal = {4'b0000,oh1[7:0]}; 
        end
        5'b01100: begin 
            control = {8'b01100000,oh1[10:8],14'b00010010000001};
            literal = {3'b000,oh1[8:0]}; 
        end
        5'b01101: begin 
            control = {11'b01100000000,oh1[10:8],11'b11010000001};
            literal = {3'b000,oh1[8:0]}; 
        end
        5'b00010: begin 
            control = {5'b00000,oh1[10:8],14'b00000000000110};
            literal = {3'b000,oh1[8:0]}; 
        end
        default: begin
            control = 26'b0;
            literal = 16'b0;
        end
    endcase
end
endmodule

