module falling_edge_capturer(
    input clk,
    input reset,
    input [23:0] in,
    output reg [23:0] out);

    reg [23:0] in_d;

    always @(posedge clk) begin
        if (reset)
            out <= 24'b0;
        else begin
            in_d <= in;
            out <= out | (in_d & ~in);
        end
    end
endmodule

