module top_module(
  input [(8 - 1):0] a,
  input [(8 - 1):0] b,
  output [(1 - 1):0] op,
  input clk,
  input ce,
  input clr
);// Declare internal wires and registers
  wire [(8 - 1):0] a_internal;
  wire [(8 - 1):0] b_internal;
  reg [(1 - 1):0] op_internal;

  // Assign inputs to internal wires
  assign a_internal = a;
  assign b_internal = b;

  // Reset output when clear signal is high
  always @(posedge clr) begin
    op_internal <= 1'b0;
  end

  // Compare inputs and update output when enable signal is high
  always @(posedge clk) begin
    if (ce) begin
      if (a_internal == b_internal) begin
        op_internal <= 1'b1;
      end else begin
        op_internal <= 1'b0;
      end
    end
  end

  // Assign internal output to module output
  assign op = op_internal;

endmodule

