  wire sel_0;
  wire sel_1;
  wire sel_2;
  wire gsel_0;
  wire gsel_1;
  wire gsel_2;
  wire oack_0;
  wire match0_0;
  wire match1_0;
  wire match2_0;
  wire [1:0] comp_0;

  assign sel_0 = match0_0;
  assign match0_0 = (i_0r1[0] & i_0r1[1]);
  assign sel_1 = match1_0;
  assign match1_0 = i_0r0[0];
  assign sel_2 = match2_0;
  assign match2_0 = (i_0r1[0] & i_0r0[1]);

  assign gsel_0 = sel_0 & icomplete_0;
  assign gsel_1 = sel_1 & icomplete_0;
  assign gsel_2 = sel_2 & icomplete_0;

  assign comp_0[0] = i_0r0[0] | i_0r1[0];
  assign comp_0[1] = i_0r0[1] | i_0r1[1];
  assign icomplete_0 = comp_0[0] & comp_0[1];

  assign o_0r = gsel_0;
  assign o_1r = gsel_1;
  assign o_2r = gsel_2;

  assign oack_0 = o_0a | o_1a | o_2a;
  assign i_0a = oack_0 & icomplete_0;
endmodule

