  input [1:0] cbit;
  input ce;
  input clk;
  input clkb;
  input d;
  input purst;
  output reg q;

  always @(posedge clk or negedge clkb) begin
    if(purst) begin
      q <= 1;
    end else if(S_R) begin
      q <= 0;
    end else if(ce) begin
      case(cbit)
        2'b00: q <= d;
        2'b01: q <= d;
        2'b10: q <= d;
        2'b11: q <= d;
      endcase
    end
  end

