module top_module(output reg [3:0] Q, input clk, reset);reg [3:0] d_ex;
    reg n_rst;

    // D flip-flops
    always @(posedge clk) begin
        Q[0] <= d_ex[0];
        Q[1] <= d_ex[1];
        Q[2] <= d_ex[2];
        Q[3] <= d_ex[3];
    end

    // D flip-flop with asynchronous reset
    always @(posedge clk, negedge reset) begin
        if (!reset) begin
            n_rst <= 1;
            d_ex <= 4'b0000;
        end else begin
            n_rst <= 0;
            d_ex[0] <= Q[3];
            d_ex[1] <= Q[0];
            d_ex[2] <= Q[1];
            d_ex[3] <= Q[2] + (Q[3] & Q[2] & Q[1] & Q[0]);
        end
    end
endmodule

