module sequence_detector (
    input clk,
    input areset,
    input bit_in,
    output reg detected);

    parameter IDLE = 2'b00, S1 = 2'b01, S10 = 2'b10, S101 = 2'b11;
    reg [1:0] state;

    always @(posedge clk or posedge areset) begin
        if (areset) begin
            state <= IDLE;
            detected <= 1'b0;
        end else begin
            case (state)
                IDLE: begin
                    if (bit_in) state <= S1;
                    detected <= 1'b0;
                end
                S1: begin
                    if (!bit_in) state <= S10;
                    else state <= IDLE;
                    detected <= 1'b0;
                end
                S10: begin
                    if (bit_in) begin
                        state <= S101;
                        detected <= 1'b1;
                    end else begin
                        state <= IDLE;
                        detected <= 1'b0;
                    end
                end
                S101: begin
                    if (bit_in) state <= S1;
                    else state <= S10;
                    detected <= 1'b0;
                end
                default: begin
                    state <= IDLE;
                    detected <= 1'b0;
                end
            endcase
        end
    end
endmodule

